                                /*copy 2 more chars because the lib always add 2 '0' at the end for UTF16 end of string*/
                                memcpy((char *) utf16Line, s_txt->text+2, sizeof(char) * (s_txt->len));
                                len = gf_utf8_wcslen((const u16*)utf16Line);
                        } else {
